reference_solution:
def maximum_ribbon_piece_length(ribbons, k):
    left, right = 0, max(ribbons)
    while left < right:
        middle = (left + right + 1) // 2
        pieces = sum(ribbon // middle for ribbon in ribbons)
        if pieces >= k:
            left = middle
        else:
            right = middle - 1
    return left

